local rows={} for i,f in ipairs(sprite.frames) do local im=Image(sprite.spec) im:drawSprite(sprite,i) local file=string.format('D:/alianximod/docs/资源库/过程归档/种火_上窜熄灭_v3_模型补档_20261115/frames/frame_%02d.png',i) im:saveAs(file) local count=0 local ymin=64 local ymax=-1 for it in im:pixels() do if app.pixelColor.rgbaA(it())>0 then count=count+1 if it.y<ymin then ymin=it.y end if it.y>ymax then ymax=it.y end end end rows[#rows+1]={frame=i,duration=f.duration,opaquePixels=count,minY=ymin,maxY=ymax,path=file} end return {width=sprite.width,height=sprite.height,frameCount=#sprite.frames,frames=rows,sourceSaved=false}
